import { access, readFile, readdir, writeFile } from 'node:fs/promises';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { format } from 'oxfmt';

// The repository formatting rules, so generated files match `pnpm format:check`.
const {
  $schema: _schema,
  ignorePatterns: _ignore,
  ...formatOptions
} = JSON.parse(await readFile(new URL('../../../.oxfmtrc.json', import.meta.url), 'utf8'));
const identifier = /^[A-Za-z_$][A-Za-z0-9_$]*$/;
const typeName = /^[a-z][a-z0-9]*(?:-[a-z0-9]+)*$/;

/** Produce static imports from opted-in repository files, without executing integration code. */
export async function generateCatalog(root, write = false) {
  const source = join(root, 'packages/integrations/src');
  const directory = join(source, 'integrations');
  const entries = [];
  for (const item of await readdir(directory, { withFileTypes: true })) {
    if (!item.isDirectory()) continue;
    const path = join(directory, item.name, 'integration.json');
    let raw;
    try {
      raw = await readFile(path, 'utf8');
    } catch (error) {
      if (error?.code === 'ENOENT') continue;
      throw error;
    }
    const entry = JSON.parse(raw);
    if (
      !entry ||
      typeof entry !== 'object' ||
      Array.isArray(entry) ||
      Object.keys(entry).some(
        (key) =>
          ![
            'type',
            'order',
            'definition',
            'backend',
            'frontend',
            'mcp',
            'scopes',
            'translations',
            'development',
          ].includes(key),
      ) ||
      entry.type !== item.name ||
      !typeName.test(entry.type) ||
      entry.type.length > 40 ||
      !Number.isSafeInteger(entry.order) ||
      entry.order < 0 ||
      typeof entry.definition !== 'string' ||
      !identifier.test(entry.definition) ||
      (entry.backend !== undefined &&
        (typeof entry.backend !== 'string' || !identifier.test(entry.backend))) ||
      (entry.frontend !== undefined &&
        (typeof entry.frontend !== 'string' || !identifier.test(entry.frontend))) ||
      (entry.mcp !== undefined && (typeof entry.mcp !== 'string' || !identifier.test(entry.mcp))) ||
      (entry.translations !== undefined && entry.translations !== true) ||
      (entry.development !== undefined && entry.development !== true) ||
      (entry.scopes !== undefined &&
        (!Array.isArray(entry.scopes) ||
          entry.scopes.length > 8 ||
          entry.scopes.some(
            (scope) =>
              !scope ||
              typeof scope !== 'object' ||
              Array.isArray(scope) ||
              Object.keys(scope).some(
                (key) => !['id', 'label', 'hint', 'labelFallback', 'hintFallback'].includes(key),
              ) ||
              typeof scope.id !== 'string' ||
              !new RegExp(`^${entry.type}:[a-z][a-z-]{1,30}$`).test(scope.id) ||
              !['label', 'hint', 'labelFallback', 'hintFallback'].every(
                (key) =>
                  typeof scope[key] === 'string' &&
                  scope[key].length > 0 &&
                  scope[key].length <= 200,
              ),
          ))) ||
      (entry.mcp !== undefined && (!entry.scopes || entry.scopes.length === 0))
    )
      throw new Error(`Invalid integration descriptor: ${item.name}`);
    await access(join(directory, item.name, 'definition.ts'));
    if (entry.backend) await access(join(directory, item.name, 'registration.ts'));
    if (entry.frontend) await access(join(directory, item.name, 'frontend.ts'));
    if (entry.mcp) await access(join(directory, item.name, 'mcp.ts'));
    if (entry.translations) await access(join(directory, item.name, 'messages.ts'));
    if (entry.development) await access(join(directory, item.name, 'development.ts'));
    entries.push(entry);
  }
  entries.sort((a, b) => a.order - b.order || a.type.localeCompare(b.type));
  if (new Set(entries.map((entry) => entry.order)).size !== entries.length)
    throw new Error('Integration descriptor order values must be unique.');
  if (new Set(entries.map((entry) => entry.definition)).size !== entries.length)
    throw new Error('Integration definition exports must be unique.');
  const scopes = entries.flatMap((entry) => entry.scopes ?? []);
  if (new Set(scopes.map((scope) => scope.id)).size !== scopes.length)
    throw new Error('Integration scope IDs must be unique.');

  const header =
    '// Generated by packages/integrations/scripts/integration-catalog.mjs; edit integration descriptors instead.\n';
  const imports = entries.map(
    (entry) => `import { ${entry.definition} } from '../integrations/${entry.type}/definition.js';`,
  );
  const definitions = `${header}import type { IntegrationDefinition } from '../integration-manifest.js';\n${imports.join('\n')}\n${entries.map((entry) => `export { ${entry.definition} };`).join('\n')}\nconst entries: readonly { type: string; definition: IntegrationDefinition }[] = [\n${entries.map((entry) => `  { type: ${JSON.stringify(entry.type)}, definition: ${entry.definition} },`).join('\n')}\n];\nfor (const entry of entries) {\n  if (entry.type !== entry.definition.type) throw new Error(\`Mismatched integration descriptor: \${entry.type}\`);\n}\nexport const integrationDefinitions: readonly IntegrationDefinition[] = entries.map(({ definition }) => definition);\nexport const integrationScopeOptions = ${JSON.stringify(scopes)} as const;\nexport const integrationAgentScopeIds = ${JSON.stringify(scopes.map((scope) => scope.id))} as const;\n`;
  function factories(kind) {
    const selected = entries.filter((entry) => entry[kind]);
    const file = kind === 'backend' ? 'registration' : kind;
    const lines = selected.flatMap((entry, index) => [
      `import { ${entry.definition} as definition${index} } from '../integrations/${entry.type}/definition.js';`,
      `import { ${entry[kind]} as factory${index} } from '../integrations/${entry.type}/${file}.js';`,
    ]);
    return `${header}${lines.join('\n')}\nexport const ${kind}Factories = [\n${selected.map((entry, index) => `  { type: ${JSON.stringify(entry.type)}, definition: definition${index}, create: factory${index} },`).join('\n')}\n];\n`;
  }
  const translated = entries.filter((entry) => entry.translations);
  const translationImports = translated.map(
    (entry, index) =>
      `import { en as en${index}, ptBR as pt${index} } from '../integrations/${entry.type}/messages.js';`,
  );
  const translations = `${header}${translationImports.join('\n')}\nexport const integrationEnglish = { ${translated.map((_, index) => `...en${index}`).join(', ')} } as const;\nexport const integrationPortuguese: Record<keyof typeof integrationEnglish, string> = { ${translated.map((_, index) => `...pt${index}`).join(', ')} };\n`;
  const developmentEntries = entries.filter((entry) => entry.development);
  const development = `${header}${developmentEntries.map((entry, index) => `import * as plugin${index} from '../integrations/${entry.type}/development.js';`).join('\n')}\nexport const developmentPlugins = [${developmentEntries.map((_, index) => `plugin${index}`).join(', ')}];\n`;
  const outputs = {
    'definitions.ts': definitions,
    'backend.ts': factories('backend'),
    'frontend.ts': factories('frontend'),
    'mcp.ts': factories('mcp'),
    'translations.ts': translations,
    'development.ts': development,
  };
  for (const [name, text] of Object.entries(outputs)) {
    const path = join(source, 'generated', name);
    const { code: formatted, errors } = await format(path, text, formatOptions);
    if (errors.length > 0) throw new Error(`Could not format ${name}: ${errors[0].message}`);
    if (write) await writeFile(path, formatted);
    else if ((await readFile(path, 'utf8')) !== formatted)
      throw new Error(`Integration catalog is stale: ${name}. Run pnpm integration:catalog.`);
  }
}

if (process.argv[1] && resolve(process.argv[1]) === import.meta.filename) {
  try {
    if (!['--check', '--write'].includes(process.argv[2]) || process.argv.length !== 3)
      throw new Error('Usage: pnpm integration:catalog');
    await generateCatalog(resolve(import.meta.dirname, '../../..'), process.argv[2] === '--write');
  } catch (error) {
    console.error(
      error instanceof Error ? error.message : 'Could not generate integration catalog.',
    );
    process.exitCode = 1;
  }
}
